item.content:encoded:
.cbv-header,
.cbv-footer {
	display: none;
}
.cbv-content {
	padding-block: 0;
}
.cbv-content .alignfull:first-child {
	margin-block-start: 0;
}
/* head Homepage */
.cbv-content .is-layout-constrained > .alignwide {
    max-width: var(--wp--style--global--wide-size);
}
.homepage-hero {
	background-image: radial-gradient(
      closest-side,
      rgba(16, 97, 174, 0.35) 0%,
      rgba(16, 97, 174, 0) 60.00000238418579%
    ),
    linear-gradient(
      124.51deg,
      rgba(139, 90, 43, 1) 0%,
      rgba(74, 42, 20, 1) 60.00000238418579%,
      rgba(26, 15, 8, 1) 100%
    ),
    linear-gradient(
      131.34deg,
      rgba(11, 46, 84, 1) 0%,
      rgba(18, 35, 58, 1) 44.999998807907104%,
      rgba(26, 21, 18, 1) 100%
    );
}
.homepage-hero .wp-block-cover__image-background {
	width: 118.05555555555556%;
	left: -9.02777777777778%;
	right: auto;
}
@media (width <= 30rem) {
	.disciplines .wp-block-buttons .wp-element-button::after {
		margin-inline-start: 0.6em;
		width: 1.1em;
		height: 1.1em;
	}
}
@media (width <= 30rem) {
	.trending .trending-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
	}
	.trending .trending-card img {
		aspect-ratio: 1 !important;
	}
	.trending .trending-card {
		padding-bottom: 1rem !important;
	}
	.trending .trending-card > h3 {
		padding: 0.199375rem 0.75rem 0 !important;
	}
	/* Mobile wraps "Pro Performance / Front Splint Boots" differently from desktop. */
	.trending .trending-card:nth-child(4) > h3 br {
		display: none;
	}
}
@media (width <= 30rem) {
	.certified .wp-block-media-text__content {
		padding: 1.6875rem 1.5rem 3.1875rem !important;
	}
	.certified .wp-block-media-text__media {
		height: 291px !important;
		min-height: 0 !important;
	}
	.certified .wp-block-media-text__media::after,
	.certified-carousel .pc-carousel__control,
	.certified .wp-block-media-text__content > p br {
		display: none;
	}
	.certified .wp-block-media-text__content > p:first-child::after {
		width: 48px;
		margin-top: 8px;
	}
	.certified .wp-block-buttons {
		flex-direction: column;
		align-items: stretch;
	}
	.certified .wp-block-button {
		width: 100%;
	}
	/* 50th anniversary logo: a 174px-high band, as in the mobile design. */
	.homepage-anniversary .wp-block-image img {
		width: 100%;
		height: 174px;
		object-fit: cover;
	}
	/* The desktop line break does not apply; the underline spans the column. */
	.homepage-anniversary h2 {
		display: block;
	}
	.homepage-anniversary h2 br {
		display: none;
	}
	.homepage-anniversary h2::after {
		width: 100%;
	}
	/* Mobile dots sit at the left and are narrower. */
	.certified-carousel .wp-block-profchoice-carousel-indicators {
		justify-content: flex-start;
	}
	/* On the dots, so it wins over the block's Default width. */
	.certified-carousel .pc-carousel-indicator {
		--pc-carousel-indicator-default-width: 8px;
	}
}
@media (width <= 30rem) {
	.sponsors .sponsors-logos {
		margin-left: 0;
		margin-right: 0;
	}
	.insider .insider-row {
		flex-direction: column;
		align-items: stretch;
	}
	.insider .insider-copy {
		flex-basis: auto !important;
	}
	.insider .insider-copy p {
		opacity: 0.82;
	}
}
/* Tablet and small desktop: the desktop layout is too tight below 1152px. */
@media (30rem < width <= 72rem) {
	.homepage-anniversary {
		padding: 3rem 2rem !important;
	}
	.homepage-anniversary .wp-block-image img {
		width: auto;
		max-height: 280px;
	}
	.certified .wp-block-media-text__content {
		padding-left: 7.5rem !important;
	}
	.certified .wp-block-media-text__content h2 {
		font-size: 2.75rem !important;
	}
	.certified .wp-block-media-text__content > p br {
		display: none;
	}
	.insider .insider-copy {
		flex: 1 1 50% !important;
	}
	.insider form {
		flex: 1 1 50%;
	}
}
/* Tablet (the @tablet range, 481–782px): stack like mobile. */
@media (30rem < width <= 48.875rem) {
	.trending .trending-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
	}
	.trending .trending-card:nth-child(4) > h3 br {
		display: none;
	}
	.certified.wp-block-media-text {
		grid-template-columns: 100% !important;
	}
	.certified .wp-block-media-text__media {
		grid-column: 1 !important;
		grid-row: 1 !important;
		height: 360px !important;
		min-height: 0 !important;
	}
	.certified .wp-block-media-text__content {
		grid-column: 1 !important;
		grid-row: 2 !important;
		padding: 2.5rem 2rem 7.375rem !important;
	}
	.certified .wp-block-media-text__media::after,
	.certified-carousel .pc-carousel__control {
		display: none;
	}
	.insider .insider-row {
		flex-direction: column;
		align-items: stretch;
	}
	.insider .insider-copy {
		flex-basis: auto !important;
	}
}
/* Hover and focus motion (classes set on the blocks; colors come from each Button's Hover/Focus/Active states). */
.wp-block-button__link {
	transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
}
/* Links with an arrow: the gap before the arrow grows, and the underline with it. */
/* As a block, so the wrapper line box (inherited body line-height) adds no height. */
.pc-link-arrow .wp-block-button__link {
	display: block;
}
.pc-link-arrow .pc-inline-icon {
	transition: margin-inline-start 0.25s ease;
}
.pc-link-arrow .wp-block-button__link:is(:hover, :focus-visible) .pc-inline-icon {
	margin-inline-start: 1.25em;
}
/* Cards and covers: the image zooms in slightly. */
.pc-hover-zoom {
	overflow: hidden;
}
.pc-hover-zoom :is(.wp-block-image img, .wp-block-cover__image-background) {
	transition: transform 0.6s ease;
}
.pc-hover-zoom:hover :is(.wp-block-image img, .wp-block-cover__image-background) {
	transform: scale(1.04);
}
@media (prefers-reduced-motion: reduce) {
	.wp-block-button__link,
	.pc-link-arrow .pc-inline-icon,
	.pc-hover-zoom :is(.wp-block-image img, .wp-block-cover__image-background) {
		transition: none;
	}
	.pc-hover-zoom:hover :is(.wp-block-image img, .wp-block-cover__image-background) {
		transform: none;
	}
}
/* Newsletter: focus shown as a soft ring around the whole form box, not the browser outline inside it. */
.insider-form {
	transition: box-shadow 0.2s ease;
}
.insider-form input[type="email"]:focus {
	outline: none;
}
.insider-form:focus-within {
	box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.35);
}
/* Keyboard focus on the button: an inner white ring (its Focus-visible state also darkens it). */
.insider-form :is(button, .wp-block-button__link):focus-visible {
	outline: none;
	/* A white line 3px inside the edge, so it reads against the red. */
	box-shadow: inset 0 0 0 3px #a8201f, inset 0 0 0 4.5px rgba(255, 255, 255, 0.9);
}
/* tail Homepage */
